from discord.ext import commandsclass YTDLPLogger:    def debug(self, msg):        if msg.startswith('[debug] '):            pass        else:            self.info(msg)    def info(self, msg):        if msg.startswith('[info] '):            pass        else:            self.warning(msg)    def warning(self, msg):        if msg.startswith('[warning] '):            pass        else:            self.error(msg)    @staticmethod    def error(msg):        if msg.startswith('[error] '):            pass